package com.hau.exam.infrastructure.persistence.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.*;@Entity@Table(name="exam_matrices")public class MatrixEntity{@Id public UUID id;@Column(nullable=false)public String name;@Column(name="faculty_id",nullable=false)public String facultyId;@Column(name="subject_id",nullable=false)public UUID subjectId;@Column(name="total_questions",nullable=false)public int totalQuestions;@Column(name="created_by",nullable=false)public UUID createdBy;@Column(name="created_at",nullable=false)public Instant createdAt;@Column(name="updated_at",nullable=false)public Instant updatedAt;@Version public long version;@OneToMany(mappedBy="matrix",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)public List<MatrixRuleEntity>rules=new ArrayList<>();}
